arguments.command:
# The $d.147 results are ARM mapping symbols, not real functions. Use nm to find the enclosing function.
for addr in 0x2f4b20 0x2f4c84 0x2c1a40; do
  dec_addr=$((addr))
  # Find the function symbol that contains this address
  awk -v target="$dec_addr" '
    $2 ~ /[TtWw]/ {
      addr = strtonum("0x" $1)
      if (addr <= target) { best_name = $3; best_addr = addr }
      if (addr > target && !done) { printf "0x%x -> %s+0x%x\n", target, best_name, target - best_addr; done=1 }
    }
    END { if (!done && best_name) printf "0x%x -> %s+0x%x\n", target, best_name, target - best_addr }
  ' /tmp/symbols/symbols.txt
done

