arguments.command:
# These addresses fall in the Cortex-A53 erratum thunk region (linker-generated patches).
# The thunks redirect to real code. Let's find the real function by looking at 
# executable (not data/object) function symbols closest before these addresses.
# Filter out thunks, mapping symbols ($d, $x), and inline label data.

awk '
  $2 ~ /[Tt]/ && $3 !~ /^__CortexA53/ && $3 !~ /^\$/ && $3 !~ /\.in_labels/ {
    addr = strtonum("0x" $1)
    name = $3
    if (addr <= 0x2f4b20) { f1 = name; a1 = addr }
    if (addr <= 0x2f4c84) { f2 = name; a2 = addr }
  }
  END {
    printf "0x2f4b20 likely in: %s (0x%x) +0x%x\n", f1, a1, 0x2f4b20 - a1
    printf "0x2f4c84 likely in: %s (0x%x) +0x%x\n", f2, a2, 0x2f4c84 - a2
