# That offset is way too large for a single function. These addresses are in linker-generated 
# erratum thunk section, which sits between real code sections. Let me check the section layout.
readelf -S /tmp/symbols/libmonosgen-2.0.so.dbg | awk '/\.text|CortexA53|erratum/' 

# Let me try to find what section these addresses are in
readelf -S /tmp/symbols/libmonosgen-2.0.so.dbg | awk '
  {
    if (match($0, /\[[ 0-9]+\]/)) {
      name = $2
      if (substr(name,1,1) == ".") {
        # Parse address and size
        for (i=3; i<=NF; i++) {
          if (length($i) == 16 && $i ~ /^[0-9a-f]+$/) {
            addr = strtonum("0x" $i)
            if (addr > 0 && addr < 0x1000000) {
              base = addr
              size = strtonum("0x" $(i+1))
              if (0x2f4b20 >= base && 0x2f4b20 < base + size) printf "0x2f4b20 in section %s (0x%x - 0x%x)\n", name, base, base+size
              break
            }
          }
        }
      }
    }
  }
'

